package main
import (
"github.com/gin-gonic/gin"
"net/http"
)
func main() {
r := gin.New()
r.Use(gin.Recovery())
r.GET("/closed", func(c *gin.Context) { c.AbortWithStatusJSON(http.StatusForbidden, gin.H{"error": "Closed for practice"}) }, func(c *gin.Context) { c.String(http.StatusOK, "This is skipped") })
r.Run("127.0.0.1:3000")
}
